function kmpContains(text, pattern) {
  // fail[i]: longest proper prefix of pattern[0..i] that is also a suffix of it
  const fail = new Array(pattern.length).fill(0);
  for (let i = 1, k = 0; i < pattern.length; i++) {
    while (k > 0 && pattern[i] !== pattern[k]) k = fail[k - 1];
    if (pattern[i] === pattern[k]) k++;
    fail[i] = k;
  }
  for (let i = 0, k = 0; i < text.length; i++) {
    while (k > 0 && text[i] !== pattern[k]) k = fail[k - 1];   // fall back, never rescan
    if (text[i] === pattern[k]) k++;
    if (k === pattern.length) return true;
  }
  return false;
}

