def kmp_contains(text, pattern):
    # fail[i]: longest proper prefix of pattern[0..i] that is also a suffix of it
    fail = [0] * len(pattern)
    k = 0
    for i in range(1, len(pattern)):
        while k > 0 and pattern[i] != pattern[k]:
            k = fail[k - 1]
        if pattern[i] == pattern[k]:
            k += 1
        fail[i] = k
    k = 0
    for token in text:
        while k > 0 and token != pattern[k]:
            k = fail[k - 1]                 # fall back, never rescan
        if token == pattern[k]:
            k += 1
        if k == len(pattern):
            return True
    return False

