    vector<int> fail(pattern.size(), 0);
    for (size_t i = 1, k = 0; i < pattern.size(); i++) {
        while (k > 0 && pattern[i] != pattern[k]) k = fail[k - 1];
        if (pattern[i] == pattern[k]) k++;
        fail[i] = k;
